with profiles(p_key,focus,case_text,boundary,source_keys) as (values
('dl-rspp-sector:costruzioni:ud1','Mappare committente, responsabile dei lavori, coordinatori, impresa affidataria, imprese esecutrici, lavoratori autonomi e relativi obblighi, evitando vuoti o sovrapposizioni di responsabilità.','Un’impresa affidataria entra con due subappaltatori e lavoratori autonomi: ricostruire chi verifica cosa prima dell’avvio e quali informazioni devono essere coordinate.','Non attribuire al DL-RSPP funzioni proprie di committente, coordinatore, dirigente o preposto.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-condivido-near-miss']::text[]),
('dl-rspp-sector:costruzioni:ud2a','Usare dati di infortunio, malattia professionale, near miss e segnali deboli del comparto per scegliere priorità concrete e verificare se DVR/POS intercettano le dinamiche reali.','Emergono quasi-infortuni con caduta materiali, urti con mezzi e posture gravose: costruire priorità per frequenza, gravità potenziale e debolezza delle barriere.','La statistica orienta le priorità ma non sostituisce la valutazione della singola impresa e del singolo cantiere.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-costruzioni-dati-2026','inail-condivido-near-miss']::text[]),
('dl-rspp-sector:costruzioni:ud2b','Leggere il cantiere come sistema dinamico: fasi, aree, accessi, logistica, sovrapposizioni, viabilità, depositi, servizi e cambiamenti devono essere pianificati e riesaminati.','Cambiano accesso mezzi, area deposito e sequenza lavori: individuare rischi e interferenze da rivalutare prima della modifica.','La pianificazione del DL-RSPP non sostituisce PSC, POS o coordinamento quando previsti.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-condivido-near-miss']::text[]),
('dl-rspp-sector:costruzioni:ud3','Tradurre le misure generali dell’art. 95 in scelte verificabili su ordine del cantiere, accessi, movimentazioni, manutenzione, cooperazione, protezioni e gestione delle fasi.','Il cronoprogramma comprime due lavorazioni nella stessa area: valutare come applicare l’art. 95 e quando la sovrapposizione non è accettabile.','Le misure generali vanno concretizzate nel cantiere e integrate con gli obblighi specifici applicabili.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-condivido-near-miss']::text[]),
('dl-rspp-sector:costruzioni:ud4','Usare il POS come documento operativo dell’impresa: organizzazione, lavorazioni, rischi, misure, attrezzature, sostanze e procedure devono essere coerenti col cantiere e aggiornati al cambiamento.','Il POS non comprende una nuova fase con PLE e demolizione parziale: decidere se iniziare e quali parti vanno riesaminate.','La LU insegna a governare il POS dell’impresa senza sostituire gli obblighi dei soggetti che lo redigono, verificano o coordinano.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-condivido-near-miss']::text[]),
('dl-rspp-sector:costruzioni:ud5','Comprendere funzione e struttura del PSC, individuare prescrizioni e interferenze che ricadono sull’impresa e verificare coerenza di POS e organizzazione operativa con il coordinamento.','Il PSC prevede viabilità separata e fasi non contemporanee, ma l’organizzazione proposta differisce: stabilire come procedere prima di iniziare.','I cenni sul PSC non conferiscono il ruolo o le competenze del CSP/CSE.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-condivido-near-miss']::text[]),
('dl-rspp-sector:costruzioni:ud6','Prevenire la caduta privilegiando eliminazione dell’esposizione e protezioni collettive, scegliendo opere provvisionali e sistemi anticaduta coerenti con accessi, bordi, aperture, coperture e piano di recupero.','Per un lavoro su copertura vengono proposti imbracature e cordini senza parapetti: verificare se la soluzione rispetta la gerarchia delle misure e quali condizioni servono prima del GO.','Non sostituisce formazione/addestramento specifici per DPI anticaduta, ponteggi o sistemi di accesso mediante funi.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-ancoraggi-cadute','inail-tutorial-cadute-2022']::text[]),
('dl-rspp-sector:costruzioni:ud7','Governare demolizioni e scavi partendo da stabilità, sottoservizi, sequenze, puntellamenti/protezioni, accessi, mezzi, materiali, atmosfere e interferenze, con chiari criteri di sospensione.','Uno scavo deve essere approfondito dopo una pioggia intensa e passa vicino a una linea interrata: definire verifiche preliminari, protezioni e STOP.','Non abilita all’uso di attrezzature né sostituisce progettazioni, verifiche strutturali o competenze tecniche specialistiche necessarie.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-quaderni-cantieri','inail-rischio-elettrico-costruzioni-2026']::text[]),
('dl-rspp-sector:costruzioni:ud8','Valutare impianti elettrici temporanei, condizioni ambientali, quadri/cavi/protezioni, messa a terra, linee aeree o interrate e illuminazione, distinguendo uso ordinario da lavori elettrici affidati a personale qualificato.','Una gru e una PLE operano vicino a una linea aerea, mentre cavi provvisori attraversano una zona umida: individuare misure, competenze e STOP.','Non forma PES/PAV/PEI e non autorizza lavori elettrici.',array['mlps-asr-2025','normattiva-dlgs81-vigente','inail-rischio-elettrico-costruzioni-2026','inail-quaderni-cantieri']::text[])
), target as (
select lu.id learning_unit_id,lu.stable_key lu_key,lu.title lu_title,lu.default_minutes,p.focus,p.case_text,p.boundary,p.source_keys,(select coalesce(max(v.version_number),0)+1 from public.learning_unit_versions v where v.learning_unit_id=lu.id) next_version,(select v.content from public.learning_unit_versions v where v.learning_unit_id=lu.id order by v.version_number desc limit 1) old_content from public.learning_units lu join profiles p on p.p_key=lu.stable_key
), built as (
select t.*,coalesce(t.old_content,'{}'::jsonb)||jsonb_build_object('title',t.lu_title,'sector','Costruzioni','ateco_reference','F','minutes',t.default_minutes,'summary','Nel modulo DL-RSPP Costruzioni il tema “'||t.lu_title||'” va governato collegando obblighi, condizioni reali di cantiere, misure, responsabilità, verifiche e criteri di STOP.','detail',t.focus||' La trattazione è orientata alla decisione: cosa verificare prima, come organizzare la misura, chi coinvolgere, quale evidenza dimostra l’attuazione e quando sospendere o rivalutare il lavoro.','focus',t.focus,'case',t.case_text,'question','Quale decisione deve assumere il Datore-RSPP prima di autorizzare o mantenere l’attività e su quali evidenze deve basarla?','question_explanation','La risposta deve collegare fatti osservabili, obblighi, gerarchia delle misure, responsabilità, competenze, STOP e verifica di efficacia. Punto chiave: '||t.focus,'procedure',jsonb_build_array('Descrivi fase e area','Individua pericoli, esposti e interferenze','Verifica piani, dati e competenze','Scegli misure secondo gerarchia','Assegna responsabilità e risorse','Definisci STOP ed emergenza','Controlla applicazione','Riesamina al cambiamento'),'common_errors',jsonb_build_array('Usare PSC/POS o procedure come documenti formali senza verificarli sul lavoro reale.','Affidarsi ai soli DPI prima delle misure collettive o organizzative.','Non aggiornare misure quando cambiano fasi, imprese, attrezzature o interferenze.','Confondere il ruolo del DL-RSPP con altri ruoli del Titolo IV.','Continuare nonostante manchi una barriera essenziale o una competenza obbligatoria.'),'operational',jsonb_build_object('before',jsonb_build_array('Definisci fase, area, lavorazione e soggetti coinvolti.','Raccogli PSC/POS/DVR e documenti pertinenti.','Verifica competenze, formazione/abilitazioni, coordinamento e misure prima dell’avvio.','Controlla accessi, viabilità, interferenze e scenario di emergenza.'),'during',jsonb_build_array('Controlla coerenza tra lavoro reale e misure definite.','Privilegia protezioni tecniche, collettive e organizzative.','Gestisci cambiamenti con decisione GO/STOP/RIVALUTA.','Mantieni comunicazione tra impresa, preposti, lavoratori e coordinamento pertinente.'),'after',jsonb_build_array('Registra anomalie, near miss e azioni correttive.','Verifica efficacia e chiusura delle azioni.','Aggiorna documenti e misure quando necessario.'),'if_problem',jsonb_build_array('Metti in sicurezza e sospendi la fase se necessario.','Non improvvisare soluzioni fuori competenza.','Coinvolgi preposto, dirigente, coordinamento e tecnico competente.','Riprendi solo dopo verifica documentata delle condizioni che avevano imposto STOP.'),'who_to_involve',jsonb_build_array('Datore/DL-RSPP','Dirigenti e preposti','Lavoratori/RLS','CSP/CSE quando pertinenti','Medico competente quando pertinente','Tecnici o specialisti competenti'),'stop_conditions',jsonb_build_array('Rischio grave non controllato.','Barriera essenziale assente o inefficace.','Piano o procedura non coerente col lavoro reale.','Attrezzatura, impianto, scavo o area in condizioni non verificate.','Competenza o abilitazione necessaria non disponibile.','Interferenza significativa non valutata.'),'adaptation','Adattare a impresa, cantiere, fase, PSC/POS, DVR, attrezzature, ambiente e organizzazione reali.'),'teacher_activity',jsonb_build_object('prompt',t.case_text,'method','Mappa fatti, rischi, obblighi, misure, responsabilità, STOP ed evidenza di efficacia; chiudi con decisione GO/NO-GO motivata.','debrief','Confrontare la decisione con Titolo IV, gerarchia delle misure e condizioni reali.'),'visuals',jsonb_build_array(jsonb_build_object('type','process','title','Ciclo di governo del rischio','steps',jsonb_build_array('FASE','PERICOLI','INTERFERENZE','MISURE','RESPONSABILI','CONTROLLO','RIESAME')),jsonb_build_object('type','hierarchy','title','Gerarchia delle misure','steps',jsonb_build_array('ELIMINA/RIDUCI','COLLETTIVE','ORGANIZZA','PROCEDURE','DPI','VERIFICA'))),'scope_boundary','Questa LU sviluppa competenze di governo del Datore-RSPP e non sostituisce corsi, abilitazioni o ruoli specialistici. '||t.boundary,'formative_check',jsonb_build_object('question','Quale condizione consente il GO e quale impone STOP o riesame?','explanation','Si procede solo quando scenario, obblighi, misure, competenze e verifiche sono coerenti; se manca una barriera essenziale non si procede.','formative_only',true,'test_builder_excluded',true),'didactic_version','dl-rspp-authored-v3','source_keys',to_jsonb(t.source_keys),'source_audit',jsonb_build_object('status','reviewed','checked_on','2026-10-16','reuse_policy','reference_and_original_rewrite'),'source_integration_note','Fonti usate per validazione normativa e tecnica; testi, casi, sequenze e spiegazioni SafetyTraining sono originali.','quality',coalesce(t.old_content->'quality','{}'::jsonb)||jsonb_build_object('teacher_ready',true,'learner_ready',true,'decision_based',true,'transfer_to_work',true,'authored_presentation',true,'question_has_explanation',true,'formative_checks_only',true,'final_assessment',false,'test_builder_excluded',true,'scope_boundary_explicit',true),'final_assessment',false,'test_builder_excluded',true) content from target t
), final as (
select b.*,b.content||jsonb_build_object('evidence_sources',(select jsonb_agg(jsonb_build_object('source_key',ts.source_key,'authority',ts.authority,'title',ts.title,'url',ts.canonical_url,'checked_on','2026-10-16','use','authored_evidence') order by ts.source_key) from unnest(b.source_keys) s(source_key) join public.training_sources ts on ts.source_key=s.source_key)) content_final from built b
)
insert into public.learning_unit_versions(learning_unit_id,version_number,status,content,content_hash,published_at) select learning_unit_id,next_version,'draft',content_final,md5(content_final::text),null from final;